import re, os, glob

root = '.'
# collect files that contain tasklet/NAPI wiring
interesting = set()
pat_trig = re.compile(r'tasklet_setup|tasklet_init|netif_napi_add|netif_napi_add_weight|napi_schedule\(')
for dirpath, dirs, files in os.walk(root):
    if '/.git' in dirpath: continue
    for f in files:
        if f.endswith(('.c', '.h')):
            p = os.path.join(dirpath, f)
            interesting.add(p)

results = []
plain = re.compile(r'(?<!irq)spin_lock\((?![^)]*irq)')
bh = re.compile(r'spin_lock_bh')
for p in sorted(interesting):
    try:
        with open(p, errors='ignore') as fh:
            lines = fh.readlines()
    except OSError:
        continue
    txt = ''.join(lines)
    if not pat_trig.search(txt):
        continue
    if 'spin_lock_bh' in txt:
        continue  # driver knows the pattern; still may mix, but deprioritize
    # count plain spin_lock( occurrences (not irqsave/irqrestore/bh/nested variants excluded? keep nested)
    plain_hits = []
    for i, l in enumerate(lines):
        s = l.strip()
        if re.search(r'\bspin_lock(_nested)?\(&', s):
            plain_hits.append(i+1)
    if plain_hits:
        results.append((len(plain_hits), p, plain_hits[:12]))

results.sort(reverse=True)
for n, p, hits in results[:40]:
    print(n, p, hits)
