149: 
150: 		vif = wil->vifs[txdata->mid];
151: 		if (unlikely(!vif)) {
152: 			wil_dbg_txrx(wil, "Invalid MID %d\n", txdata->mid);
153: 			continue;
154: 		}
155: 
156: 		tx_done += wil_tx_complete(vif, i);
157: 	}
158: 
159: 	if (tx_done < budget) {
160: 		napi_complete(napi);
