162: 		wil_dbg_txrx(wil, "NAPI TX complete\n");
163: 	}
164: 
165: 	wil_dbg_txrx(wil, "NAPI TX poll(%d) done %d\n", budget, tx_done);
166: 
167: 	return min(tx_done, budget);
168: }
