import re, subprocess, os, collections

roots = ["drivers/","net/","kernel/","mm/","fs/","block/","crypto/","lib/","security/","ipc/","sound/","virt/"]
files = subprocess.run(["grep","-rln","tasklet_init\\|DECLARE_TASKLET\\|netif_napi_add\\|napi_schedule","--include=*.c"]+roots,capture_output=True,text=True).stdout.split()

# Step 1: build map func_name -> (file, body, start, end) for all C files in dirs containing softirq registrations
dirs = set()
for f in files:
    dirs.add(os.path.dirname(f))
# also add sibling dirs? keep to containing dir + same driver subtree (parent dir)
scan_files = []
for d in sorted(dirs):
    p = subprocess.run(["find",d,"-maxdepth","1","-name","*.c"],capture_output=True,text=True).stdout.split()
    scan_files += p
    # parent level to catch multi-file drivers (e.g. drivers/net/ethernet/x/y)
    pd = os.path.dirname(d)
    p2 = subprocess.run(["find",pd,"-maxdepth","1","-name","*.c"],capture_output=True,text=True).stdout.split()
    scan_files += p2
scan_files = sorted(set(scan_files))
print("scan files:", len(scan_files))

def parse_functions(src):
    funcs = []
    lines = src.split('\n')
    i = 0; n = len(lines)
    while i < n:
        m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*\(', lines[i])
        if m:
            k = i; started = False
            while k < n and k < i + 12:
                if '{' in lines[k]: started = True; break
                if lines[k].rstrip().endswith(';'): break
                k += 1
            if started:
                depth = 0; end = None
                for k2 in range(k, n):
                    depth += lines[k2].count('{') - lines[k2].count('}')
                    if depth == 0:
                        end = k2; break
                if end is not None:
                    funcs.append((m.group(1), i+1, end+1, '\n'.join(lines[i:end+1])))
                    i = end + 1; continue
        i += 1
    return funcs

LOCK_RE = re.compile(r'(spin_lock\w*)\s*\(\s*&?\s*([A-Za-z0-9_\.\->\[\]\(\)]+?)\s*[,)]')

# func definitions across scan files
func_defs = {}   # name -> list of (file, sl, el, body)
for f in scan_files:
    try: src = open(f).read()
    except: continue
    for (name, sl, el, body) in parse_functions(src):
        func_defs.setdefault(name, []).append((f, sl, el, body))

# softirq-side functions per driver dir
dir_softirq = collections.defaultdict(set)
for f in files:
    src = open(f).read()
    for m in re.finditer(r'tasklet_init\s*\(\s*&[^,]+,\s*([A-Za-z0-9_]+)\s*,', src):
        dir_softirq[f].add(m.group(1))
    for m in re.finditer(r'DECLARE_TASKLET[^;]*?\(\s*[^,]+,\s*([A-Za-z0-9_]+)\s*,', src):
        dir_softirq[f].add(m.group(1))
    for m in re.finditer(r'netif_napi_add(?:_compat)?\s*\(([^;]*?)\)\s*;', src, re.S):
        args = [a.strip() for a in m.group(1).split(',')]
        if len(args) >= 3:
            mm = re.match(r'^&?([A-Za-z0-9_]+)$', args[2])
            if mm: dir_softirq[f].add(mm.group(1))

# group by driver directory (parent of file dir where appropriate)
# build per-file function lock usage
file_fn_locks = {}
for f in scan_files:
    try: src = open(f).read()
    except: continue
    d = {}
    for (name, sl, el, body) in parse_functions(src):
        for m in LOCK_RE.finditer(body):
            d.setdefault(name, []).append((m.group(1), m.group(2), sl + body[:m.start()].count('\n')))
    file_fn_locks[f] = d

results = []
for reg_file, softirq_fns in dir_softirq.items():
    # resolve each softirq fn to its defining file within the same driver dir/parent
    drv = os.path.dirname(reg_file)
    parent = os.path.dirname(drv)
    for fn in softirq_fns:
        defs = func_defs.get(fn, [])
        def_site = None
        for (df, sl, el, body) in defs:
            if os.path.dirname(df) in (drv, parent) or df == reg_file:
                def_site = (df, sl, el, body)
                break
        if not def_site: continue
        df, sl, el, body = def_site
        # expand: softirq fn + direct callees in same driver files
        softirq_set = {fn}
        # direct calls within body
        for callee in set(re.findall(r'\b([a-z][a-z0-9_]*)\s*\(', body)):
            if callee in ('spin_lock','spin_unlock','spin_lock_irqsave','spin_unlock_irqrestore','spin_lock_bh','spin_unlock_bh','spin_lock_irq','spin_unlock_irq','kmalloc','kfree','memcpy','memset','dev_kfree_skb','dev_kfree_skb_any','dev_kfree_skb_irq'): continue
            cdefs = func_defs.get(callee, [])
            for (cf, csl, cel, cbody) in cdefs:
                if os.path.dirname(cf) in (drv, parent):
                    softirq_set.add(callee)
                    break
        # gather locks from softirq set
        slocks = {}
        for sfn in softirq_set:
            for (df2, sl2, el2, body2) in func_defs.get(sfn, []):
                if os.path.dirname(df2) not in (drv, parent): continue
                for m in LOCK_RE.finditer(body2):
                    slocks.setdefault(m.group(2), []).append((sfn, m.group(1), df2, sl2 + body2[:m.start()].count('\n')))
        if not slocks: continue
        # plain spin_lock sites across driver files
        for f2 in file_fn_locks:
            if os.path.dirname(f2) not in (drv, parent): continue
            for fn2, lst in file_fn_locks[f2].items():
                if fn2 in softirq_set: continue
                for (v, lock, line) in lst:
                    if v != 'spin_lock': continue
                    base = lock.split('->')[-1].split('.')[-1]
                    for slock, sinfo in slocks.items():
                        sbase = slock.split('->')[-1].split('.')[-1]
                        if base == sbase and base not in ('lock','flags','') and len(base) > 3:
                            results.append((f2, lock, fn2, line, sinfo[:2]))

for r in sorted(set(results)):
    print(r)
